#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include <talloc.h>

#include <asn1c/ber_tlv_tag.h>
#include <asn1c/INTEGER.h>

/* Applications generated by asn1c provide the allocator root context. */
void *talloc_asn1_ctx;

int main(void) {
    uint8_t encoded[8] = {0};
    const uint8_t expected[] = {0x02};
    const size_t size = ber_tlv_tag_serialize(
        ASN_TAG_CLASS_UNIVERSAL | (2 << 2), encoded, sizeof(encoded));
    if (size != sizeof(expected) || memcmp(encoded, expected, sizeof(expected)) != 0)
        return 1;
    if (asn_DEF_INTEGER.name == NULL || asn_DEF_INTEGER.name[0] == '\0')
        return 2;

    void *context = talloc_new(NULL);
    if (context == NULL)
        return 3;
    char *copy = talloc_strdup(context, "asn1c");
    if (copy == NULL || strcmp(copy, "asn1c") != 0)
        return 4;
    talloc_free(context);

    puts("LIBASN1C_CONSUMER_OK");
    return 0;
}
